mapper.select:
SELECT * FROM platform_wallet
WHERE platform_wallet_id = #{platformWalletId}
    FOR UPDATE

mapper.update:
UPDATE platform_wallet
SET balance = balance - #{amount},
    freeze_amount = freeze_amount - #{amount},
    total_payout = total_payout + #{amount},
    update_time = NOW()
WHERE platform_wallet_id = #{platformWalletId}
  AND balance >= #{amount}
  AND freeze_amount >= #{amount}
